<?php declare(strict_types='1'); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Password Pattern Checker','description'=>'Check a password for repeated characters and simple sequential patterns.','url'=>'https://smarttoolz.in/tools/password-pattern-checker/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Password Pattern Checker</h1><p>Detect obvious repeated and sequential patterns.</p></section><section class="tool-workspace"><div class="tool-panel"><input id="p" type="password" placeholder="Enter password"><button id="go" class="tool-btn">Check Pattern</button><p id="o"></p></div></section></main><script>go.onclick=()=>{let s=p.value,rep=/(.)\1\1/.test(s),seq=/0123|1234|2345|abcd|bcde|cdef/i.test(s);o.textContent=`Repeated characters: ${rep?'Found':'None'} · Sequential pattern: ${seq?'Found':'None'}`}</script><?php smarttoolz_tool_page_end(); ?>